from datetime import datetime, timezone

# service -> (attempt limit, backoff cap, longest accepted Retry-After)
_PROFILES = {
    "shipping": (8, 3, 40),
    "catalog": (6, 8, 30),
    "ledger": (8, 3, 60),
    "auth": (6, 6, 20),
    "payments": (3, 1, 30),
    "ledger-export": (4, 8, 10),
    "reports": (9, 5, 120),
    "inventory": (7, 4, 90),
    "search": (10, 12, 45),
    "media": (5, 8, 15),
}
_DEFAULT = (5, 8, 120)
_IDEMPOTENT = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_RETRYABLE = {429, 502, 503, 504}
_MONTHS = {m: i + 1 for i, m in enumerate(
    "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split())}
_DAYS = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
_DATE_RE = re.compile(
    r"([A-Za-z]{3}), (\\d{2}) ([A-Za-z]{3}) (\\d{4}) (\\d{2}):(\\d{2}):(\\d{2}) GMT")


def _get(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name:
            return v
    return None


def _retry_after(value, now):
    """Seconds to wait, or None if absent/malformed."""
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value, re.ASCII):
        return float(int(value))
    m = _DATE_RE.fullmatch(value)
    if not m:
        return None
    day_name, d, mon, y, hh, mm, ss = m.groups()
    if day_name not in _DAYS or mon not in _MONTHS:
        return None
    try:
        when = datetime(int(y), _MONTHS[mon], int(d), int(hh), int(mm),
                        int(ss), tzinfo=timezone.utc)
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())
''')
